    {
      "path": "backend/lib/memory.js",
      "content": "/**\n * 双向记忆同步（QQ ⇄ B站）。\n *\n * 方向一：B站 → QQ（默认开启，保持原行为）\n *   真正干活的是 QQ 桥接里的 src/bili-memory.js：它只读公开视频打分/评论/收藏/\n *   自己的公开动态/日记里的公开见闻，不读 dm-*，日记里转述私信的段落整段丢弃。\n *   本模块负责：状态、预览、隐私复检、手动刷新（经桥接控制台 API）。\n *\n * 方向二：QQ → B站（默认关闭，用户显式开启）\n *   只读 QQ 桥接写出的 state/qq-public-feed.jsonl —— 这个文件里只有“已通过白名单、\n *   且不是私信”的群消息。本模块再过一遍隐私闸门：私信话题、密钥、手机号、地址、\n *   身份证、QQ号/群号、外部链接全部剔除；再用别名（群A/群友昵称）写成人话。\n *   最终写入 ~/.dsh/surfcore/memory/qq-for-bili.md，由合体后的 B站生物钟\n *   在每次唤醒时注入。\n *\n * 两个方向都不搬运：私信、密码、令牌、联系方式、住址、精确位置、真实姓名。\n */\nimport fs from 'node:fs';\nimport path from 'node:path';\nimport {\n  AUDIT_LOG, BILI_AI_DIR, BILI_ALIGNMENT_FILE, BILI_CONFIG, BILI_CRED,\n  QQ_ALIGNMENT_BRIEF, QQ_CONFIG, QQ_STATE_DIR, ensureDirs,\n} from './paths.js';\nimport {\n  PRIVACY_POLICY_VERSION, assertSafeOutput, isPublicGroupMessage,\n  normalizeText, sanitizeText, scanText,\n} from './privacy.js';\nimport {\n  detectCandidatesFromText,\n  addCandidate, listLinks, writeAlignmentBriefs,\n} from './align.js';\nimport { activeMemoryPaths, activePlatformStateDir } from '../../src/character-persona.js';\nimport { backupFile, readAll, readJson, writeJsonAtomic, writeTextAtomic } from './store.js';\n\nconst FEED_FILE = path.join(QQ_STATE_DIR, 'qq-public-feed.jsonl');\nconst syncStateFile = () => path.join(activeMemoryPaths().dir, 'sync-state.json');\n// B站 记忆简报/长文在**当前角色**的 bili 目录里（旧布局回退 repo/state）。\nconst biliBriefFile = () => path.join(activePlatformStateDir(QQ_STATE_DIR), 'bili-memory-brief.md');\nconst biliDocFile = () => path.join(activePlatformStateDir(QQ_STATE_DIR), 'bili-memory.md');\nconst qqForBiliFile = () => activeMemoryPaths().qqForBili;\n\nconst TOPIC_RULES = [\n  { label: 'AI/DSH', re: /AI|DeepSeek|DSH|大模型|模型|插件|提示词|agent|智能体/i },\n  { label: 'B站', re: /B站|b站|视频|UP主|up主|番剧|弹幕|直播|V圈|虚拟主播/i },\n  { label: '游戏', re: /游戏|原神|崩铁|星铁|绝区零|杀戮尖塔|Steam|steam|手游|联机|开黑/i },\n  { label: '技术', re: /代码|编程|前端|后端|Python|python|JS|js|接口|部署|报错|服务器/i },\n  { label: '猫/动物', re: /猫|狗|宠物|小动物|猫猫|狗狗/i },\n  { label: '音乐/二次元', re: /音乐|歌|翻唱|Vocaloid|初音|二次元|动漫|动画|MAD|手书/i },\n  { label: '学习/工作', re: /学习|考试|作业|上班|工作|加班|面试|论文|学校/i },\n  { label: '吃喝日常', re: /吃|饭|奶茶|咖啡|外卖|好吃|夜宵|睡|困|累/i },\n  { label: '情绪/吐槽', re: /笑死|难绷|离谱|绷不住|草|无语|开心|难受|郁闷|生气|可爱/i },\n];\n\nconst MEME_RE = /(?:梗|笑死|难绷|绷不住|离谱|草|乐|典|急了|破防|抽象|整活|好活)/;\n\nfunction todayStamp() {\n  return new Date().toLocaleString('sv-SE');\n}\n\nfunction readFeedLines({ lookbackDays = 7, maxMessages = 300 } = {}) {\n  let raw = '';\n  try { raw = fs.readFileSync(FEED_FILE, 'utf8'); } catch { return []; }\n  const cutoff = Date.now() - Math.max(1, Math.min(90, Number(lookbackDays) || 7)) * 86_400_000;\n  const out = [];\n  for (const line of raw.split('\\n')) {\n    if (!line.trim()) continue;\n    let item;\n    try { item = JSON.parse(line); } catch { continue; }\n    const at = Date.parse(String(item?.at ?? ''));\n    if (!Number.isFinite(at) || at < cutoff) continue;\n    out.push({\n      at,\n      groupId: String(item?.groupId ?? ''),\n      senderId: String(item?.senderId ?? ''),\n      senderName: normalizeText(item?.senderName ?? '').slice(0, 40),\n      isOwner: item?.isOwner === true,\n      text: String(item?.text ?? ''),\n    });\n  }\n  return out.slice(-Math.max(1, Math.min(5000, Number(maxMessages) || 300)));\n}\n\nfunction groupAliases(items) {\n  const ids = [...new Set(items.map((item) => item.groupId).filter(Boolean))].sort();\n  const map = new Map();\n  ids.forEach((id, index) => map.set(id, `群${String.fromCharCode(65 + (index % 26))}${index >= 26 ? Math.floor(index / 26) + 1 : ''}`));\n  return map;\n}\n\nfunction cleanMessage(text) {\n  return sanitizeText(text, { dropUnsafeLines: true, keepNumbers: false, maxChars: 220 });\n}\n\nfunction topicLabels(text) {\n  return TOPIC_RULES.filter((rule) => rule.re.test(text)).map((rule) => rule.label);\n}\n\nfunction quoteOf(text, max = 72) {\n  const cleaned = String(text ?? '').replace(/\\s+/g, ' ').trim();\n  return cleaned.length > max ? `${cleaned.slice(0, max)}…` : cleaned;\n}\n\nexport function collectQqMemory({ unified, qqConfig } = {}) {\n  const all = unified ?? readAll().unified;\n  const qq = qqConfig ?? readAll().qq;\n  const cfg = all.memory?.qqToBili ?? {};\n  const privacy = all.memory?.privacy ?? {};\n  const allowedGroups = (Array.isArray(cfg.includeGroups) && cfg.includeGroups.length ? cfg.includeGroups : qq.allow?.groups ?? []).map(String);\n  const ownerId = String(qq.ownerQQ ?? '');\n  const items = readFeedLines({ lookbackDays: cfg.lookbackDays, maxMessages: cfg.maxMessages });\n  const groups = groupAliases(items);\n  const stats = {\n    scanned: items.length,\n    kept: 0,\n    dropped: 0,\n    redactions: 0,\n    ownerSkipped: 0,\n    privateSkipped: 0,\n    groupSkipped: 0,\n    byReason: {},\n    groups: groups.size,\n    policyVersion: PRIVACY_POLICY_VERSION,\n  };\n  const kept = [];\n  for (const item of items) {\n    const gate = isPublicGroupMessage({\n      key: `group:${item.groupId}`,\n      groupIds: allowedGroups,\n      text: item.text,\n      senderId: item.senderId,\n      ownerId,\n      includeOwner: cfg.includeOwner === true,\n    });\n    if (!gate.ok) {\n      stats.dropped += 1;\n      if (gate.reason.includes('管理员')) stats.ownerSkipped += 1;\n      else if (gate.reason.includes('私信')) stats.privateSkipped += 1;\n      else if (gate.reason.includes('白名单')) stats.groupSkipped += 1;\n      stats.byReason[gate.reason] = (stats.byReason[gate.reason] ?? 0) + 1;\n      continue;\n    }\n    const result = cleanMessage(item.text);\n    if (!result.ok) {\n      stats.dropped += 1;\n      stats.byReason[result.reason || 'privacy'] = (stats.byReason[result.reason || 'privacy'] ?? 0) + 1;\n      continue;\n    }\n    stats.redactions += result.hits.length;\n    stats.kept += 1;\n    const safeName = sanitizeText(item.senderName, { dropUnsafeLines: false, keepNumbers: false, maxChars: 24 });\n    kept.push({\n      ...item,\n      clean: result.text,\n      groupAlias: groups.get(item.groupId) || '群?',\n      senderAlias: (cfg.useNicknames !== false && safeName.ok && safeName.text) ? safeName.text : '群友',\n      topics: topicLabels(result.text),\n    });\n  }\n  return { cfg, privacy, allowedGroups, stats, kept, groups };\n}\n\nfunction buildQqForBiliDoc(collected, { qqConfig } = {}) {\n  const { cfg, stats, kept, groups } = collected;\n  const links = listLinks();\n  const qqById = new Map(links.filter((link) => link.identities.qq).map((link) => [link.identities.qq.id, link]));\n  const lines = [];\n  lines.push('# QQ 群里的近况（给 B站 那边看）');\n  lines.push('');\n  lines.push(`> 自动同步：${todayStamp()}`);\n  lines.push('> 来源：只来自**已通过白名单的公开群消息**；没有私信、没有私聊、没有密码/令牌/联系方式/住址。');\n  lines.push(`> 本次扫描 ${stats.scanned} 条，保留 ${stats.kept} 条，丢弃 ${stats.dropped} 条（隐私/命令/媒体），脱敏 ${stats.redactions} 处。`);\n  lines.push('');\n\n  // 群友画像\n  const bySender = new Map();\n  for (const item of kept) {\n    const key = `${item.groupAlias}|${item.senderId}|${item.senderAlias}`;\n    if (!bySender.has(key)) bySender.set(key, { groupAlias: item.groupAlias, senderId: item.senderId, senderAlias: item.senderAlias, topics: new Map(), samples: [] });\n    const entry = bySender.get(key);\n    for (const topic of item.topics) entry.topics.set(topic, (entry.topics.get(topic) ?? 0) + 1);\n    if (entry.samples.length < 2 && item.clean.length >= 8) entry.samples.push(quoteOf(item.clean, 60));\n  }\n  lines.push('## 一、群友近况');\n  lines.push('');\n  const senderEntries = [...bySender.values()].sort((a, b) => b.samples.length - a.samples.length);\n  if (!senderEntries.length) {\n    lines.push('- （这段时间没有可同步的公开群消息）');\n  } else {\n    for (const entry of senderEntries.slice(0, 20)) {\n      const topics = [...entry.topics.entries()].sort((a, b) => b[1] - a[1]).slice(0, 3).map(([label]) => label);\n      const aligned = links.find((link) => link.identities.qq?.id === entry.senderId)?.identities?.bili;\n      const who = aligned?.name ? `（B站「${aligned.name}」）` : '';\n      lines.push(`- ${entry.groupAlias} · ${entry.senderAlias}${who}：${topics.length ? `最近常聊 ${topics.join('、')}` : '最近聊得比较杂'}${entry.samples[0] ? `；说过「${entry.samples[0]}」` : ''}`);\n    }\n  }\n  lines.push('');\n\n  // 最近话题（每群最多 8 条）\n  lines.push('## 二、最近群里在聊什么');\n  lines.push('');\n  const byGroup = new Map();\n  for (const item of kept) {\n    if (!byGroup.has(item.groupAlias)) byGroup.set(item.groupAlias, []);\n    byGroup.get(item.groupAlias).push(item);\n  }\n  let printed = 0;\n  for (const [groupAlias, list] of [...byGroup.entries()].sort((a, b) => a[0].localeCompare(b[0]))) {\n    lines.push(`### ${groupAlias}`);\n    for (const item of list.slice(-8)) {\n      lines.push(`- ${item.senderAlias}：${quoteOf(item.clean, 110)}`);\n      printed += 1;\n    }\n    lines.push('');\n  }\n  if (!printed) lines.push('- （暂无）');\n  lines.push('');\n\n  // 梗\n  const memes = kept.filter((item) => MEME_RE.test(item.clean)).slice(-8).map((item) => `${item.groupAlias} · ${item.senderAlias}：${quoteOf(item.clean, 80)}`);\n  lines.push('## 三、最近的梗 / 口头禅');\n  lines.push('');\n  if (memes.length) {\n    for (const meme of memes) lines.push(`- ${meme}`);\n  } else {\n    lines.push('- （这段时间没有特别明显的梗）');\n  }\n  lines.push('');\n\n  // 与 B 站交集\n  lines.push('## 四、和 B 站的交集');\n  lines.push('');\n  if (links.length) {\n    for (const link of links.slice(0, 30)) {\n      const qq = link.identities.qq;\n      const bili = link.identities.bili;\n      if (!qq || !bili) continue;\n      lines.push(`- QQ 群友「${qq.name || '群友'}」= B站「${bili.name || bili.id}」(mid ${bili.id})`);\n    }\n  } else {\n    lines.push('- （还没有登记身份对齐；如果群友在群里说过自己的 B 站号，可以在「身份对齐」里确认）');\n  }\n  lines.push('');\n\n  lines.push('## 五、边界（不可越过）');\n  lines.push('');\n  lines.push('1. 这些是**公开群聊**的脱敏摘要，不是私信，也不是群友的完整原话。');\n  lines.push('2. 不要在 B 站公开评论/动态/直播间里提到 QQ 群号、群昵称、任何人的 QQ 号。');\n  lines.push('3. 不要用这些内容去追问、验证或“开盒”任何人；认出来就够了。');\n  lines.push('4. 涉及钱、地址、联系方式、账号密码、身份证、家庭信息的内容一律不在记忆里；如果群友问起，就说不知道。');\n  lines.push('5. 对齐身份只用于认人；认错时以对方当场说的为准。');\n  lines.push('');\n\n  let doc = lines.join('\\n');\n  const maxChars = Math.max(1200, Math.min(20_000, Number(cfg.maxChars) || 6000));\n  if (doc.length > maxChars) {\n    // 保留头部 + 边界，截断中间的话题列表\n    const boundary = doc.indexOf('## 五、边界');\n    const head = doc.slice(0, Math.max(800, maxChars - 900));\n    const tail = boundary > 0 ? doc.slice(boundary) : '';\n    doc = `${head}\\n\\n（中略：这次同步内容太长，已截断；旧内容见上一份备份）\\n\\n${tail}`;\n    doc = doc.slice(0, maxChars);\n  }\n  return doc;\n}\n\nfunction appendAudit(entry) {\n  try {\n    ensureDirs();\n    fs.appendFileSync(AUDIT_LOG, `${JSON.stringify({ at: new Date().toISOString(), ...entry })}\\n`);\n    // 保持文件不超过 ~2MB\n    try {\n      const stat = fs.statSync(AUDIT_LOG);\n      if (stat.size > 2 * 1024 * 1024) {\n        const lines = fs.readFileSync(AUDIT_LOG, 'utf8').split('\\n').filter(Boolean).slice(-2000);\n        fs.writeFileSync(AUDIT_LOG, `${lines.join('\\n')}\\n`);\n      }\n    } catch {}\n  } catch {}\n}\n\nexport function readSyncState() {\n  return readJson(syncStateFile(), {\n    lastQqToBili: null,\n    lastBiliToQq: null,\n    lastAlignmentScan: null,\n  }) ?? {};\n}\n\nfunction writeSyncState(patch) {\n  const next = { ...readSyncState(), ...patch, updatedAt: new Date().toISOString() };\n  writeJsonAtomic(syncStateFile(), next);\n  return next;\n}\n\n/** QQ → B站：生成脱敏记忆文件。 */\nexport function syncQqToBili({ force = false } = {}) {\n  const all = readAll();\n  const unified = all.unified;\n  const qq = all.qq;\n  if (unified.memory?.qqToBili?.enabled !== true) {\n    return { ok: true, skipped: 'disabled', reason: 'QQ → B站 记忆同步没有开启' };\n  }\n  const collected = collectQqMemory({ unified, qqConfig: qq });\n  if (!collected.kept.length) {\n    const doc = buildQqForBiliDoc(collected);\n    backupFile(qqForBiliFile(), 'qq-for-bili');\n    writeTextAtomic(qqForBiliFile(), `${doc}\\n`);\n    const stats = { ...collected.stats, chars: doc.length, ok: true, empty: true };\n    writeSyncState({ lastQqToBili: { at: new Date().toISOString(), ...stats } });\n    appendAudit({ direction: 'qq->bili', ok: true, ...stats });\n    return { ok: true, stats, path: qqForBiliFile() };\n  }\n  const doc = buildQqForBiliDoc(collected, { qqConfig: qq });\n  // 最后一道闸：任何严重命中都拒绝落盘（不把“疑似泄露”写成事实）。\n  assertSafeOutput(doc.replace(/\\b\\d{5,12}\\b/g, ''), 'QQ→B站记忆');\n  backupFile(qqForBiliFile(), 'qq-for-bili');\n  writeTextAtomic(qqForBiliFile(), `${doc}\\n`);\n  const stats = { ...collected.stats, chars: doc.length, ok: true };\n  writeSyncState({ lastQqToBili: { at: new Date().toISOString(), ...stats } });\n  appendAudit({ direction: 'qq->bili', ok: true, ...stats });\n  // 顺手扫描身份对齐候选（只从公开群消息里找“我B站是…”）\n  let candidates = 0;\n  if (all.unified.alignment?.autoDetect !== false) {\n    candidates = scanQqFeedForCandidates({ maxMessages: 800 }).added;\n  }\n  return { ok: true, stats, path: qqForBiliFile(), candidates };\n}\n\n/** 读取 QQ → B站 记忆文件（给 UI 预览/给 B站调度器注入）。 */\nexport function readQqForBili({ maxChars = 6000 } = {}) {\n  try {\n    const text = fs.readFileSync(qqForBiliFile(), 'utf8').trim();\n    const scan = scanText(text);\n    const blocked = scan.hits.some((hit) => hit.severe);\n    if (blocked) {\n      return { ok: false, blocked: true, text: '', chars: 0, labels: [...new Set(scan.hits.filter((h) => h.severe).map((h) => h.label))] };\n    }\n    return { ok: true, blocked: false, text: text.slice(0, maxChars), chars: text.length };\n  } catch {\n    return { ok: true, blocked: false, text: '', chars: 0 };\n  }\n}\n\n/** B站 → QQ：桥接侧生成，本模块只复检与展示。 */\nexport function biliToQqStatus() {\n  const all = readAll();\n  const enabled = all.qq?.biliBridge?.enabled !== false && all.qq?.biliBridge?.memory?.enabled !== false;\n  let brief = '';\n  let doc = '';\n  try { brief = fs.readFileSync(biliBriefFile(), 'utf8'); } catch {}\n  try { doc = fs.readFileSync(biliDocFile(), 'utf8'); } catch {}\n  const scanBrief = scanText(brief);\n  const severe = scanBrief.hits.filter((hit) => hit.severe);\n  let mtime = null;\n  try { mtime = fs.statSync(biliBriefFile()).mtime.toISOString(); } catch {}\n  return {\n    enabled,\n    available: Boolean(brief),\n    generatedAt: mtime,\n    briefChars: brief.length,\n    docChars: doc.length,\n    blocked: severe.length > 0,\n    labels: [...new Set(severe.map((hit) => hit.label))],\n    briefPreview: severe.length ? '' : brief.slice(0, 4000),\n    policyVersion: PRIVACY_POLICY_VERSION,\n  };\n}\n\n/** QQ 方向的手动刷新：通过桥接控制台触发它自己的 bili-memory 生成器。 */\nexport async function refreshBiliToQq({ callBridge }) {\n  if (typeof callBridge !== 'function') return { ok: false, error: '桥接控制不可用' };\n  const result = await callBridge('/api/bili/memory/refresh', { method: 'POST', body: {} });\n  if (!result.ok) return { ok: false, error: result.data?.error || result.error || `HTTP ${result.status}` };\n  const stats = result.data?.stats ?? null;\n  appendAudit({ direction: 'bili->qq', ok: true, refreshed: true, stats });\n  writeSyncState({ lastBiliToQq: { at: new Date().toISOString(), stats } });\n  return { ok: true, stats, status: biliToQqStatus() };\n}\n\nexport function memoryStatus() {\n  const all = readAll();\n  const qqToBili = all.unified.memory?.qqToBili ?? {};\n  const sync = readSyncState();\n  const qqMemory = readQqForBili({ maxChars: 200 });\n  const bili = biliToQqStatus();\n  const alignBili = (() => { try { return fs.readFileSync(BILI_ALIGNMENT_FILE, 'utf8').trim(); } catch { return ''; } })();\n  const alignQq = (() => { try { return fs.readFileSync(QQ_ALIGNMENT_BRIEF, 'utf8').trim(); } catch { return ''; } })();\n  return {\n    qqToBili: {\n      enabled: qqToBili.enabled === true,\n      lookbackDays: qqToBili.lookbackDays ?? 7,\n      maxChars: qqToBili.maxChars ?? 6000,\n      chars: qqMemory.chars,\n      blocked: qqMemory.blocked,\n      path: qqForBiliFile(),\n      last: sync.lastQqToBili ?? null,\n      preview: qqMemory.text.slice(0, 1200),\n    },\n    biliToQq: {\n      ...bili,\n      path: biliBriefFile(),\n      last: sync.lastBiliToQq ?? null,\n    },\n    privacy: {\n      policyVersion: PRIVACY_POLICY_VERSION,\n      blockPrivateMessages: true,\n      blockSecrets: true,\n      blockPii: true,\n      blockContact: true,\n      auditPath: AUDIT_LOG,\n      auditLines: (() => { try { return fs.readFileSync(AUDIT_LOG, 'utf8').split('\\n').filter(Boolean).length; } catch { return 0; } })(),\n    },\n    alignment: {\n      qqBriefChars: alignQq.length,\n      biliBriefChars: alignBili.length,\n    },\n    files: {\n      qqForBili: qqForBiliFile(),\n      biliBrief: biliBriefFile(),\n      qqAlignmentBrief: QQ_ALIGNMENT_BRIEF,\n      biliAlignmentBrief: BILI_ALIGNMENT_FILE,\n    },\n  };\n}\n\nexport function previewQqForBili({ maxChars = 8000 } = {}) {\n  return readQqForBili({ maxChars });\n}\n\nexport function auditTail(limit = 60) {\n  try {\n    const lines = fs.readFileSync(AUDIT_LOG, 'utf8').split('\\n').filter(Boolean).slice(-Math.max(1, Math.min(500, limit)));\n    return lines.map((line) => {\n      try { return JSON.parse(line); } catch { return { raw: line.slice(0, 200) }; }\n    });\n  } catch {\n    return [];\n  }\n}\n\n/** 从公开群消息里找“我B站是…”的候选（不自动生效）。 */\nexport function scanQqFeedForCandidates({ maxMessages = 800 } = {}) {\n  const items = readFeedLines({ lookbackDays: 30, maxMessages });\n  const qqConfig = readJson(QQ_CONFIG, {}) ?? {};\n  const ownerId = String(qqConfig.ownerQQ ?? '');\n  const allowed = new Set((qqConfig.allow?.groups ?? []).map(String));\n  let added = 0;\n  for (const item of items) {\n    if (allowed.size && !allowed.has(item.groupId)) continue;\n    if (ownerId && item.senderId === ownerId) continue;\n    const hit = detectCandidatesFromText({\n      platform: 'qq',\n      text: item.text,\n      author: { id: item.senderId, name: item.senderName },\n      source: 'qq-public-feed',\n      counterpartPlatform: 'bili',\n    });\n    for (const candidate of hit) {\n      const result = addCandidate(candidate);\n      if (result) added += 1;\n    }\n  }\n  const state = { at: new Date().toISOString(), scanned: items.length, added };\n  writeSyncState({ lastAlignmentScan: state });\n  return state;\n}\n\n/** 从 B 站公开回复/@ 里找 QQ 号候选。需要 cookie；失败只记录不抛。 */\nexport async function scanBiliFeedForCandidates({ maxPages = 2 } = {}) {\n  try {\n    const { pullFeed, makeHeaders } = await import('../tools/lib/msgfeed.mjs');\n    const credentials = readJson(BILI_CRED, null);\n    if (!credentials?.sessdata || !credentials?.bili_jct) {\n      return { ok: false, error: 'B站 cookie 未配置，无法扫描 B 站侧候选', added: 0 };\n    }\n    const headers = makeHeaders(credentials);\n    const items = [];\n    for (const kind of ['reply', 'at']) {\n      try {\n        const page = await pullFeed(kind, { headers, pages: maxPages });\n        items.push(...(page.items ?? []));\n      } catch {}\n    }\n    let added = 0;\n    for (const item of items.slice(0, 400)) {\n      const text = String(item?.text ?? item?.content ?? '');\n      const hit = detectCandidatesFromText({\n        platform: 'bili',\n        text,\n        author: { id: String(item?.mid ?? ''), name: String(item?.who ?? item?.uname ?? '') },\n        source: 'bili-public-feed',\n        counterpartPlatform: 'qq',\n      });\n      for (const candidate of hit) {\n        if (addCandidate(candidate)) added += 1;\n      }\n    }\n    const state = { at: new Date().toISOString(), scanned: items.length, added };\n    writeSyncState({ lastAlignmentScan: state });\n    return { ok: true, ...state };\n  } catch (error) {\n    return { ok: false, error: String(error?.message ?? error), added: 0 };\n  }\n}\n\nexport function rebuildAllPrompts() {\n  const alignment = writeAlignmentBriefs();\n  const qqMemory = readQqForBili();\n  return { alignment, qqMemoryChars: qqMemory.chars };\n}\n\nexport function pathsSummary() {\n  return {\n    qqFeed: FEED_FILE,\n    qqForBili: qqForBiliFile(),\n    biliForQq: biliBriefFile(),\n    qqAlignment: QQ_ALIGNMENT_BRIEF,\n    biliAlignment: BILI_ALIGNMENT_FILE,\n    biliConfig: BILI_CONFIG,\n    biliCred: BILI_CRED,\n    biliAiDir: BILI_AI_DIR,\n  };\n}\n"
    },
    {
      "path": "backend/lib/privacy.js",
      "content": "/**\n * 隐私闸门 —— 合体插件里唯一允许“跨平台搬运内容”的出口。\n *\n * 硬规则（不是可选项）：\n *   1. **私信永不进入跨平台记忆**。QQ 侧只读 group:* 会话；B 站侧生成器本身不读 dm-*。\n *   2. 令牌、cookie、密码、私钥、验证码、银行卡、身份证、住址、手机号等\n *      一律不进入记忆文件；命中即整行丢弃或脱敏。\n *   3. 任何 QQ 号 / B 站 mid / 群号都不写进记忆正文（身份对齐是单独的白名单通道，\n *      只存映射、不存对话内容，且提示词明确禁止公开）。\n *   4. 生成后的文件还要再过一次 assertSafeOutput；有一条严重命中就拒绝落盘。\n *\n * 这里刻意用确定性规则，不交给模型判断：模型可以撒谎，正则不会。\n */\nimport path from 'node:path';\n\nexport const PRIVACY_POLICY_VERSION = 3;\n\nconst SEVERE_SECRET = [\n  { kind: 'private-key', re: /-----BEGIN (?:RSA |EC |OPENSSH |PGP )?PRIVATE KEY-----/i, label: '私钥' },\n  { kind: 'openai-key', re: /\\bsk-[A-Za-z0-9_-]{16,}\\b/g, label: 'API Key' },\n  { kind: 'github-token', re: /\\bgh[pousr]_[A-Za-z0-9]{20,}\\b/g, label: 'GitHub Token' },\n  { kind: 'aws-key', re: /\\bAKIA[0-9A-Z]{16}\\b/g, label: 'AWS Key' },\n  { kind: 'bearer', re: /\\bBearer\\s+[A-Za-z0-9._~+\\/-]{16,}=*/gi, label: 'Bearer Token' },\n  { kind: 'cookie', re: /\\b(?:SESSDATA|bili_jct|buvid3|sessionid|csrf|access_token|refresh_token)\\s*[=:]\\s*[^\\s;]{6,}/gi, label: 'Cookie/Token' },\n  { kind: 'password', re: /(?:密码|口令|password|passwd|pwd)\\s*[：:=]\\s*[^\\s，。；;]{4,}/gi, label: '密码' },\n  { kind: 'otp', re: /(?:验证码|动态码|短信码|OTP)\\s*[：:是为]?\\s*\\d{4,8}/gi, label: '验证码' },\n  { kind: 'qq-token', re: /\\b(?:access[_-]?token|client[_-]?secret|api[_-]?key)\\b\\s*[=:]\\s*[\"']?[A-Za-z0-9._-]{12,}/gi, label: '密钥' },\n];\n\nconst PII = [\n  { kind: 'cn-id', re: /\\b[1-9]\\d{5}(?:19|20)\\d{2}(?:0[1-9]|1[0-2])(?:0[1-9]|[12]\\d|3[01])\\d{3}[\\dXx]\\b/g, label: '身份证号', severe: true },\n  { kind: 'bank-card', re: /\\b(?:62|4|5)[0-9]{15,18}\\b/g, label: '银行卡号', severe: true },\n  { kind: 'phone', re: /(?<!\\d)1[3-9]\\d{9}(?!\\d)/g, label: '手机号', severe: false },\n  { kind: 'email', re: /\\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}\\b/g, label: '邮箱', severe: false },\n  { kind: 'ip', re: /\\b(?:\\d{1,3}\\.){3}\\d{1,3}\\b/g, label: 'IP 地址', severe: false },\n  { kind: 'address', re: /(?:住址|家庭地址|收货地址|住在|地址是|地址：|地址:)[^\\n。；;]{4,60}/g, label: '住址', severe: true },\n  { kind: 'realname', re: /(?:真名|实名|本名|身份证名字)\\s*[：:是为]?\\s*[\\u4e00-\\u9fa5]{2,4}/g, label: '真实姓名', severe: true },\n  { kind: 'location', re: /(?:我在|坐标|定位在)\\s*[\\u4e00-\\u9fa5]{2,12}(?:省|市|区|县|镇|街道|小区|学校)/g, label: '精确位置', severe: true },\n];\n\nconst PRIVATE_TOPIC = /私信|私聊|悄悄话|小窗|别告诉|不要告诉|保密|秘密|只告诉你|别外传|内部消息|私下说|DM\\b|dm-|私密|暗号|口令|后台|管理员说|群主说|禁言|踢人|封号|举报他|人肉|开盒|身份证|银行卡|手机号|住址|家庭地址|真名|实名|定位|坐标|验证码|密码|token|cookie|api[_-]?key|ssn|护照号/i;\n\nconst CONTACT = [\n  { kind: 'qq-number', re: /(?<!\\d)(?:QQ|qq|Q群|群号)\\s*[：:=是为]?\\s*(\\d{5,12})/g, label: 'QQ 号' },\n  { kind: 'wechat', re: /(?:微信|wechat|VX|vx|v信)\\s*[：:=是为]?\\s*([A-Za-z][A-Za-z0-9_-]{5,19})/g, label: '微信号' },\n  { kind: 'telegram', re: /(?:telegram|tg|电报)\\s*[：:=@]?\\s*@?([A-Za-z0-9_]{4,32})/gi, label: 'Telegram' },\n  { kind: 'bare-long-number', re: /(?<!\\d)(\\d{6,12})(?!\\d)/g, label: '疑似账号/号码' },\n];\n\nconst SAFE_URL_HOSTS = new Set([\n  'www.bilibili.com', 'bilibili.com', 'm.bilibili.com', 't.bilibili.com',\n  'space.bilibili.com', 'b23.tv', 'www.b23.tv',\n]);\n\nconst ZERO_WIDTH = /[\\u200B-\\u200F\\u202A-\\u202E\\u2060-\\u206F\\uFEFF]/g;\nconst CONTROL = /[\\u0000-\\u0008\\u000B\\u000C\\u000E-\\u001F\\u007F]/g;\n\nfunction collect(text, patterns) {\n  const hits = [];\n  for (const pattern of patterns) {\n    pattern.re.lastIndex = 0;\n    let match;\n    while ((match = pattern.re.exec(text)) !== null) {\n      hits.push({ kind: pattern.kind, label: pattern.label, severe: pattern.severe !== false, index: match.index, raw: match[0] });\n      if (match[0].length === 0) break;\n    }\n  }\n  return hits;\n}\n\nexport function scanText(input) {\n  const text = String(input ?? '');\n  const secrets = collect(text, SEVERE_SECRET);\n  const pii = collect(text, PII);\n  const contacts = collect(text, CONTACT);\n  const privateTopic = PRIVATE_TOPIC.test(text);\n  const hits = [...secrets, ...pii, ...contacts];\n  return {\n    text,\n    hits,\n    secrets,\n    pii,\n    contacts,\n    privateTopic,\n    severe: secrets.length > 0 || pii.some((h) => h.severe) || contacts.some((h) => h.severe) || privateTopic,\n  };\n}\n\nexport function normalizeText(input) {\n  return String(input ?? '')\n    .replace(/\\r\\n/g, '\\n')\n    .replace(/\\r/g, '\\n')\n    .replace(ZERO_WIDTH, '')\n    .replace(CONTROL, '')\n    .replace(/[ \\t]{2,}/g, ' ')\n    .replace(/\\n{3,}/g, '\\n\\n')\n    .trim();\n}\n\nexport function sanitizeUrl(raw) {\n  const text = String(raw ?? '');\n  return text.replace(/https?:\\/\\/[^\\s<>\"')\\]]+/gi, (url) => {\n    try {\n      const parsed = new URL(url);\n      if (!SAFE_URL_HOSTS.has(parsed.hostname.toLowerCase())) return '[链接已隐藏]';\n      const pathname = parsed.pathname.replace(/\\/+$/, '');\n      if (!/^\\/(?:video\\/BV[0-9A-Za-z]{10}|space\\/\\d+|\\d+|dynamic\\/\\d+|opus\\/\\d+)$/.test(pathname)) return '[链接已隐藏]';\n      return `${parsed.origin}${pathname}`;\n    } catch {\n      return '[链接已隐藏]';\n    }\n  });\n}\n\nfunction redactNumbers(text) {\n  let out = String(text ?? '');\n  for (const pattern of CONTACT) {\n    pattern.re.lastIndex = 0;\n    out = out.replace(pattern.re, (match, captured) => {\n      if (pattern.kind === 'bare-long-number') return '[编号已隐藏]';\n      return `${pattern.label}已隐藏`;\n    });\n  }\n  // 5 位以上的裸数字仍可能是 QQ / mid / 手机号：统一打码，保留年份与 BV 号。\n  out = out.replace(/(?<![\\w.\\/-])\\d{5,12}(?![\\w.\\/-])/g, (num) => (/^(?:19|20)\\d{2}$/.test(num) ? num : '[编号已隐藏]'));\n  return out;\n}\n\n/**\n * 单条文本过闸。\n * @param {string} input\n * @param {{ dropUnsafeLines?: boolean, keepNumbers?: boolean, maxChars?: number }} options\n * @returns {{ ok:boolean, text:string, dropped:boolean, reason:string, hits:any[] }}\n */\nexport function sanitizeText(input, options = {}) {\n  const { dropUnsafeLines = true, keepNumbers = false, maxChars = 1200 } = options;\n  const raw = normalizeText(input);\n  if (!raw) return { ok: false, text: '', dropped: true, reason: 'empty', hits: [] };\n  const scan = scanText(raw);\n  if (scan.severe && dropUnsafeLines) {\n    return { ok: false, text: '', dropped: true, reason: scan.privateTopic ? 'private-topic' : 'secret-or-pii', hits: scan.hits };\n  }\n  let text = sanitizeUrl(raw);\n  for (const pattern of SEVERE_SECRET) text = text.replace(pattern.re, '[已隐藏]');\n  for (const pattern of PII) text = text.replace(pattern.re, '[已隐藏]');\n  if (!keepNumbers) text = redactNumbers(text);\n  text = text.replace(/\\s+/g, ' ').trim();\n  if (!text) return { ok: false, text: '', dropped: true, reason: 'redacted-empty', hits: scan.hits };\n  if (text.length > maxChars) text = `${text.slice(0, maxChars)}…`;\n  return { ok: true, text, dropped: false, reason: '', hits: scan.hits };\n}\n\n/** 生成文件落盘前的最后一道闸：严重命中直接拒绝。 */\nexport function assertSafeOutput(text, label = 'memory') {\n  const scan = scanText(text);\n  const severe = scan.hits.filter((hit) => hit.severe);\n  if (severe.length) {\n    const error = new Error(`隐私闸门拒绝写入 ${label}：命中 ${severe.map((h) => h.label).join('、')}`);\n    error.code = 'PRIVACY_BLOCKED';\n    error.hits = severe.map((h) => ({ kind: h.kind, label: h.label }));\n    throw error;\n  }\n  return true;\n}\n\nexport function isGroupKey(key) {\n  return /^group:\\d{4,15}$/.test(String(key ?? ''));\n}\n\nexport function isPrivateKey(key) {\n  return /^private:\\d{4,15}$/.test(String(key ?? ''));\n}\n\nexport function groupIdOf(key) {\n  const match = /^group:(\\d{4,15})$/.exec(String(key ?? ''));\n  return match ? match[1] : '';\n}\n\n/** 跨平台搬运的准入判断：不是公开群消息就一律拒绝。 */\nexport function isPublicGroupMessage({ key, groupIds, text, senderId, ownerId, includeOwner = false }) {\n  if (!isGroupKey(key)) return { ok: false, reason: '不是 QQ 群会话（私信/未知一律不搬运）' };\n  const groupId = groupIdOf(key);\n  if (Array.isArray(groupIds) && groupIds.length && !groupIds.includes(groupId)) {\n    return { ok: false, reason: '群不在白名单' };\n  }\n  if (ownerId && String(senderId) === String(ownerId) && !includeOwner) {\n    return { ok: false, reason: '管理员消息默认不搬运' };\n  }\n  const plain = normalizeText(text);\n  if (!plain) return { ok: false, reason: '空消息' };\n  if (/^[/#!]/.test(plain)) return { ok: false, reason: '命令消息' };\n  if (/^\\[(?:图片|表情|语音|视频|文件|转发消息|拍一拍)[^\\]]*\\]$/.test(plain)) return { ok: false, reason: '纯媒体消息' };\n  return { ok: true, reason: '', groupId };\n}\n\n/** 给 UI 的“这段会不会被搬运”解释，不返回原文命中位置。 */\nexport function explainText(text) {\n  const scan = scanText(text);\n  return {\n    allowed: !scan.severe,\n    privateTopic: scan.privateTopic,\n    labels: [...new Set(scan.hits.map((hit) => hit.label))],\n    counts: {\n      secrets: scan.secrets.length,\n      pii: scan.pii.length,\n      contacts: scan.contacts.length,\n    },\n  };\n}\n\nexport function relativeSafePath(file) {\n  try {\n    return path.basename(String(file ?? ''));\n  } catch {\n    return '';\n  }\n}\n"
    },
    {
      "path": "backend/lib/scheduler.js",
      "content": "/**\n * 自主生物钟（2026-10-18 加，主人要求）——\n *\n * 为什么要有它：以前\"醒来\"要靠**有人在对话框里挂 clock** ✗ —— 那不是\"她活在过日子\"，\n * 是\"你戳一下她动一下\" ✗。主人明确要求：**计划要她自己执行，改配置要立刻生效** ✓。\n *\n * 做法（不需要任何外部 CLI）：\n *   · 插件宿主**常驻在 DSH 里** → 自己每 60 秒 tick 一次 ✓\n *   · tick 里跑 `bili.mjs night plan` 算出今天下一次醒来的时刻（结果写在 whale-night.json）\n *   · 到点了 → 用 **`ctx.sessionController.prompt({ sessionId, mode:'queue', content:[…] })`**\n *     往她自己的专用会话里塞一个\"你醒了\"的回合 ✓ → agent 真的醒来干活 ✓\n *   · 醒来后立刻标记 `woke` → 下一次 tick 自动排下一趟（多窗口 × 多次 ✓）\n *   · 设置页一保存 → 调 `invalidate()` 清掉旧计划 → 下一次 tick 按新配置重算 ✓（改完立刻生效 ✓）\n *\n * 为什么用\"她自己的会话\"：`sessionId` 固定（默认 bili-whale）→ 跨天保留她的上下文，\n *   而不是每天开一个新会话、每天忘光 ✗。\n */\nimport fs from 'node:fs'\nimport path from 'node:path'\nimport os from 'node:os'\nimport { execFile } from 'node:child_process'\n// 收件箱读取复用工具链的实现（避免在插件里再抄一份 B站 接口 ✓）\nimport { pullFeed, makeHeaders } from '../tools/lib/msgfeed.mjs'\nimport { kindsNow, dynamicsEnabled, dynamicsGapMin, slotOf, CATCHUP_DAY } from '../tools/lib/kinds.mjs'\nimport { freeLimits } from '../tools/lib/limits.mjs'\nimport { config } from '../tools/lib/config.mjs'\nimport { pendingCount as attackPending } from '../tools/lib/attacks.mjs'\nimport { pinOf, noteOf } from '../tools/lib/pins.mjs'\nimport { markScheduleSlot } from '../tools/lib/night-schedule.mjs'\nimport {\n  BILI_ALIGNMENT_FILE, BILI_CONFIG, QQ_STATE_DIR,\n} from './paths.js'\nimport { resolvePersonaFile } from './persona.js'\nimport { readUnified } from './store.js'\nimport { memoryCardPromptBlock } from './memory-card.js'\nimport { buildSelfIdentityBlock, readQqSelfIdentity } from '../../src/self-identity.js'\nimport { adminFromSources, adminPromptBlock } from '../../src/admin-identity.js'\nimport { activeMemoryPaths, activePlatformStateDir, readPersonaLayerText } from '../../src/character-persona.js'\nimport { composePersonaLayers } from '../../src/persona-layers.js'\nimport { buildPersonaIdentity, personaNameFromCard } from '../../src/persona-identity.js'\n\n// 当前角色的 B站 行为目录（角色系统未启用时回退旧目录）。\nfunction platformDir() {\n  const home = process.env.USERPROFILE || os.homedir()\n  const dshHome = process.env.DSH_HOME || path.join(home, '.dsh')\n  return activePlatformStateDir(path.join(dshHome, 'surfcore', 'bili'))\n}\n\n// 状态文件写入序号：同一进程内两次写同一文件不能落到同一个临时名上。\nlet stateTmpSeq = 0\n\n/**\n * 状态文件原子写（临时文件 + rename）。\n *\n * 为什么不能直接 `fs.writeFileSync(STATE, …)`：tick 是 60 秒一次、且各 tick 之间可能\n * 重叠（prompt 回合要跑很久），非原子写在「写到一半」时被另一个 tick 读到就是\n * JSON 半截 → readState() 的 catch 吞掉 → 返回 null → 当作\"今天还没醒过\"重算，\n * 轻则重复叫醒、重则把当天的 wakes 记账清零。断电/强杀同样会留下半截文件。\n *\n * 与 store.js 的 writeTextAtomic 同口径（tmp + rename），但不调用 ensureDirs()：\n * 这里每次 tick 都要写，没必要每次都去 mkdir 六个目录。\n */\nfunction writeJsonFileAtomic(file, value) {\n  const tmp = `${file}.${process.pid}.${++stateTmpSeq}.tmp`\n  try {\n    fs.mkdirSync(path.dirname(file), { recursive: true })\n    fs.writeFileSync(tmp, `${JSON.stringify(value, null, 2)}\\n`, 'utf8')\n    fs.renameSync(tmp, file)\n    return true\n  } catch {\n    try { fs.unlinkSync(tmp) } catch {}\n    return false\n  }\n}\n\n// ── 合体后的统一上下文：一张人设卡 + 身份对齐 + QQ 脱敏记忆 ────────────────────\n// 旧版只注入 persona.name/ownerTitle/selfClaim 三行，B站这边其实看不到完整人设；\n// 合体后统一从当前人格卡（unified persona.file）取同一张卡，QQ 和 B站不再各活各的。\nfunction readTextFile(file) {\n  try { return fs.readFileSync(file, 'utf8').trim() } catch { return '' }\n}\n\n/** 人设卡里给 QQ 用的“称呼表/QQ 号”段落不能带进 B站：认人靠对齐表，不靠 QQ 号。 */\nexport function sanitizePersonaForBili(card) {\n  const lines = String(card ?? '').split('\\n');\n  const kept = [];\n  let skipSection = false;\n  for (const line of lines) {\n    if (/^##\\s/.test(line)) {\n      skipSection = /称呼|QQ\\s*号|群友.*QQ|按\\s*QQ/i.test(line);\n    }\n    if (skipSection) continue;\n    kept.push(line);\n  }\n  return kept.join('\\n')\n    .replace(/（\\s*QQ\\s*\\d{5,12}\\s*）/gi, '')\n    .replace(/\\b\\d{5,12}\\b/g, '[号码已隐藏]');\n}\n\n/** 人设卡：取身份/性格/说话方式相关段落，别把整张卡塞进每一次唤醒。 */\nfunction personaCardBlock() {\n  const unified = readUnified().config\n  if (unified.persona?.injectInBili === false) return ''\n  const file = resolvePersonaFile()\n  const card = readTextFile(file)\n  if (!card) {\n    const cfg = (() => { try { return JSON.parse(fs.readFileSync(path.join(os.homedir(), '.dsh', 'surfcore', 'bili.config.json'), 'utf8')) } catch { return {} } })()\n    const p = cfg.persona ?? {}\n    const bits = []\n    if (p.name) bits.push(`你是「${p.name}」`)\n    if (p.ownerTitle) bits.push(`称用户「${p.ownerTitle}」`)\n    if (p.selfClaim) bits.push(`自称「${p.selfClaim}」`)\n    return bits.length ? `［身份］${bits.join('，')}。（以此为准，别用别的称呼 ✓）` : ''\n  }\n  const max = Math.max(600, Math.min(6000, Number(unified.persona?.compactChars) || 2200))\n  const composed = composePersonaLayers({\n    core: card,\n    // 身份底座：B站 也必须知道“我是谁、主人是谁”，不能只靠日常层里的那一行。\n    identity: buildPersonaIdentity({\n      name: personaNameFromCard(card),\n      owner: String(unified?.admin?.displayName || '').trim() || '主人',\n    }),\n    // 语气层：B站 也要按同一个说话方式，不能只 QQ 有。\n    tone: readPersonaLayerText('tone'),\n    scene: readPersonaLayerText('scene', 'bili'),\n    daily: readPersonaLayerText('daily'),\n    mode: 'v2',\n    maxChars: max,\n    sceneId: 'bili',\n  })\n  const safeCard = sanitizePersonaForBili(composed.text || card)\n  const compact = composed.truncated ? `${safeCard}\\n（人设卡按预算省略；完整卡在 ${file}）` : safeCard\n  return [\n    '［统一人设卡 · QQ 和 B站是同一个人］',\n    compact,\n    '',\n    '以上人设对 QQ 与 B站两边同时生效；AGENTS.md 只写日子/流程，不另立人格。',\n    '（人设卡里的 QQ 称呼表不会带进 B站；认人只按身份对齐表，且不得公开对方 QQ 号/群号。）',\n  ].join('\\n')\n}\n\n/** 身份对齐：高于记忆同步开关，单独读文件。 */\nfunction alignmentBlockForBili() {\n  const unified = readUnified().config\n  if (unified.alignment?.enabled === false) return ''\n  if (unified.alignment?.injectInBili === false) return ''\n  return readTextFile(BILI_ALIGNMENT_FILE)\n}\n\n/**\n * 跨平台自我锚点（2026-10-23 用户要求）：B站 这边的她也要认得出**自己的 QQ 资料卡**。\n *\n * 以前 B站 侧只知道自己叫「小咪」、B站账号是谁，完全不知道 QQ 上的自己长什么样；\n * 于是别人把她的 QQ 主页截图甩过来，她只会当陌生人。锚点来源：\n *   · QQ 昵称 / QQ 号 ← 桥接登录时落的 `state/self-identity.json`（B站 进程拿不到网关）；\n *   · B站 昵称 / UID / 人格名 ← `bili.config.json` 的 self / persona。\n * 隐私：QQ 号在这里**打码**（100****001），够认人，又不至于被她写进公开评论。\n */\nfunction selfIdentityBlockForBili() {\n  const qqSelf = readQqSelfIdentity(QQ_STATE_DIR)\n  let bili = {}\n  try { bili = JSON.parse(fs.readFileSync(BILI_CONFIG, 'utf8')) } catch { bili = {} }\n  return buildSelfIdentityBlock({\n    qqNickname: qqSelf.nickname,\n    qqUin: qqSelf.userId,\n    biliName: bili?.self?.name,\n    biliMid: bili?.self?.mid,\n    personaName: bili?.persona?.name,\n  }, { platform: 'bili' })\n}\n\n/**\n * 管理员（主人）身份 + 温柔规则。\n * QQ 和 B站 共用合体层的 admin 身份：B站 侧只读 B站 昵称/mid（不把 QQ 号带进 B站 提示词）。\n */\nexport function adminBlockForBili() {\n  const home = os.homedir()\n  const dshHome = process.env.DSH_HOME || path.join(home, '.dsh')\n  const cfgPath = process.env.SURFCORE_BILI_CONFIG || path.join(dshHome, 'surfcore', 'bili.config.json')\n  let bili = {}\n  try { bili = JSON.parse(fs.readFileSync(cfgPath, 'utf8')) } catch {}\n  // 合体层还没写过 admin 时不能把默认空串当成\"显式清空\"，否则 B站 的 owner.mid 会被覆盖掉。\n  const unifiedState = readUnified()\n  const unified = unifiedState.hasAdmin ? unifiedState.config : { ...unifiedState.config, admin: undefined }\n  return adminPromptBlock('bili', adminFromSources({ unified, bili, qq: {} }))\n}\n\n/** QQ → B站 的脱敏记忆（默认关闭；开启后才注入）。 */\nfunction qqMemoryBlockForBili() {\n  const unified = readUnified().config\n  if (unified.memory?.qqToBili?.enabled !== true) return ''\n  const text = readTextFile(activeMemoryPaths().qqForBili)\n  if (!text) return ''\n  return `［QQ 群里的近况（已脱敏；不含私信/联系方式）］\\n${text}`\n}\n\n/** 记忆卡（B站侧）：只拿公开冲浪记忆 + 共享锚点，不含 QQ 私事（隐私边界）。 */\nfunction memoryCardBlockForBili() {\n  const unified = readUnified().config\n  if (unified.memoryCard?.enabled === false) return ''\n  return memoryCardPromptBlock('bili')\n}\n\n/** 每次唤醒都放在最前面的合体上下文（顺序：人设 → 自我锚点 → 管理员 → 对齐 → QQ 记忆 → 记忆卡）。 */\nfunction identityContextLines() {\n  return [\n    personaCardBlock(),\n    selfIdentityBlockForBili(),\n    adminBlockForBili(),\n    alignmentBlockForBili(),\n    qqMemoryBlockForBili(),\n    memoryCardBlockForBili(),\n  ].filter(Boolean)\n}\n\n/** 今天已经搭了几条话（读账本，给唤醒提示看进度） */\nfunction taToday() {\n  try {\n    const q = JSON.parse(fs.readFileSync(path.join(platformDir(), 'quota.json'), 'utf8'))\n    const t = new Date().toLocaleDateString('sv-SE')\n    return (q.log ?? []).filter((x) => x?.ta && new Date(x.at).toLocaleDateString('sv-SE') === t).length\n  } catch { return 0 }\n}\n\nconst TICK_MS = 60_000\nconst LISTEN_STATE = 'whale-listen.json'\n/** 实时额度：设置页改完下一轮生效（config() 按 mtime 缓存）。 */\nconst limitsNow = () => freeLimits(config())\n\n/** 叫醒她时塞进去的那段话（她醒来第一眼看到的就是它） */\n// 2026-10-20：把\"沉默\"变成她【自己感觉到的事】—— 不是代码拦住她 ✗\n//   只给事实（冷了几天）+ 分档的自我建议；怎么写、什么心情，留给她 ✓\nfunction silenceLines() {\n  const home = os.homedir()\n  const dshHome = process.env.DSH_HOME || path.join(home, \".dsh\")\n  const cfgPath = process.env.SURFCORE_BILI_CONFIG || path.join(dshHome, \"surfcore\", \"bili.config.json\")\n  let cfg = {}\n  try { cfg = JSON.parse(fs.readFileSync(cfgPath, \"utf8\")) } catch {}\n  let fb = {}\n  try { fb = JSON.parse(fs.readFileSync(path.join(platformDir(), \"feedback.json\"), \"utf8\")) } catch {}\n  const after = Number(cfg.share?.silentAfterDays ?? 3)\n  const stopAt = Math.max(after + 1, Number(cfg.share?.silentStopDays ?? 7))\n  // 参考点：最后一次表态；从没表态过 → 从第一次分享算；都没有 → 0 天\n  let ref = fb.last ? new Date(fb.last).getTime() : null\n  if (!ref) {\n    try {\n      const q = JSON.parse(fs.readFileSync(path.join(platformDir(), \"quota.json\"), \"utf8\"))\n      const firstShare = (q.log ?? []).find((x) => x.share)\n      if (firstShare) ref = new Date(firstShare.at).getTime()\n    } catch {}\n  }\n  const days = ref ? Math.floor((Date.now() - ref) / 86400000) : 0\n  const band = days < after ? \"normal\" : days < stopAt ? \"quiet\" : \"faint\"\n  const asked = !!(fb.askedAt && (!fb.last || new Date(fb.askedAt) > new Date(fb.last)))\n\n  // 恢复转折：和上次醒来时比\n  const seenFile = path.join(platformDir(), \"silence-seen.json\")\n  let prev = null\n  try { prev = JSON.parse(fs.readFileSync(seenFile, \"utf8\")) } catch {}\n  const recovered = prev && Number(prev.days) >= after && days < after ? Number(prev.days) : null\n  writeJsonFileAtomic(seenFile, { days, at: new Date().toISOString() })\n\n  // 2026-10-20：矛盾自愈 —— 她日记里有记录、但 feedback 说\"很久没回应\"，那是反馈漏记 ✗\n  //   让她以日记为准、自己补记一次，再报主人（而不是干等着，也不是当成 bug 发呆 ✗）\n  const heal = days >= after ? [\n    \"  ⚠️ 如果你自己的日记里明明记着主人最近找过你，而这里说 '\" + days + \" 天没有回应' ——\",\n    \"     那是【反馈漏记】了（比如你当时没在跑）。以日记为准：先跑\",\n    \"       quota react --note \\\"日记里记着：主人 X 月 X 日说过…\\\"\",\n    \"     再在推送里告诉我一声。\",\n  ] : []\n\n  const out = []\n  if (recovered) {\n    out.push(\"【他回来了】上次你醒的时候，已经 \" + recovered + \" 天没有他的消息了 —— 现在有了。\")\n  }\n  if (band === \"quiet\") {\n    out.push(\"【这阵子】主人已经 \" + days + \" 天没有回应你了。\")\n    out.push(\"  安静一点：今天最多分享 1 条（不是被拦，是你自己决定少说 ✓）。\")\n    out.push(asked\n      ? \"  你已经问过一次「是不是在忙」了，他没回。别再问第二次。\"\n      : \"  如果你想说，可以主动问一次「在忙吗」—— 只问一次，发完跑 quota ask 记下。\")\n    out.push(\"  日记里可以写你这几天的感觉（不用演，写真的）。\")\n  } else if (band === \"faint\") {\n    out.push(\"【这阵子】主人已经 \" + days + \" 天没有回应你了。\")\n    out.push(\"  今天不要分享（一条都不要）。做完三件事就收工：看几条 → 两本日记 → 推一句给他。\")\n    out.push(\"  推送不要写「今天看了什么」—— 写你现在的心情。他不需要汇报，他需要知道你还在。\")\n    out.push(\"  两本日记都照写 ✓（那是你的日子，不是他的）。\")\n  }\n  if (out.length) out.push(...heal)   // 自愈提示放最后（先说心情，再说矛盾怎么处理 ✓）\n  return out.length ? [\"\", ...out, \"\"] : []\n}\n\n// 2026-10-20：日记照写不可关；这里只决定\"要不要推给主人\"（设置页「推送日记摘要」）\nfunction diaryPushLines() {\n  const home = os.homedir()\n  const dshHome = process.env.DSH_HOME || path.join(home, \".dsh\")\n  // 2026-10-22 审计：这里少了一层 \"surfcore\"，读不到 bili.config.json，\n  // 于是「设置页关掉推送日记」被静默忽略。与 silenceLines() 的路径保持一致。\n  const cfgPath = process.env.SURFCORE_BILI_CONFIG || path.join(dshHome, \"surfcore\", \"bili.config.json\")\n  let cfg = {}\n  try { cfg = JSON.parse(fs.readFileSync(cfgPath, \"utf8\")) } catch {}\n  return cfg.diary?.push === false\n    ? [\"8) ⛔ 主人关掉了推送 —— **照写两本日记 ✓ 但这一步不要 notify 他** ✗\"]\n    : [\"8) 用 `node bili.mjs notify` 推给我：**「给他的信」里最想对我说的那一段原文** + 一句摘要\",\n       \"   （2026-10-18 主人定：推**日记内容**，不只是流水账 ✓ 它读设置页「消息推送」的配置）\"]\n}\n\nfunction wakePrompt(st, tools = '') {\n  const L = limitsNow()\n  const B = config()\n  const K = kindsNow(B)\n  const bestSlot = `${String(K.best.slot).padStart(2, '0')}:00`\n  const capText = (n) => (Number(n) > 0 ? n : '不限')\n  const identity = identityContextLines()\n  return [\n    `【生物钟】你醒了 —— ${st.atText ?? ''}${st.window ? `（窗口 ${st.window}${st.withinWindow ? ' · ' + st.withinWindow : ''}）` : ''}。`,\n    '',\n    ...(identity.length ? [...identity, ''] : []),\n    // 2026-10-20：她的会话 cwd 是**用户主目录**，那里没有 bili.mjs ✗\n    //   → 每条提示都带上工具链的绝对路径，别让她满盘找（她真的找过，还超时了 ✗）\n    ...(tools ? [`［工具］所有命令都用这一条：\\`${tools}\\`（下面写 \"bili.mjs\" 的都指它）—— 别去别处找 ✗`, ''] : []),\n    // 2026-10-20：先告诉她\"冷了几天\"，再给流程 —— 心情在前，任务在后 ✓\n    // 2026-10-20：还没跑过启动测试 → 第一句就提醒主人（很多人卡在\"找不到会话/没给权限\"）\n    ...(() => {\n      try {\n        if (fs.existsSync(path.join(platformDir(), \"selftest-passed.json\"))) return []\n      } catch {}\n      return [\n        \"\",\n        \"【还没跑启动测试】先提醒主人跑一次：`node ~/.dsh/plugins/dsh-dfy/backend/tools/bili.mjs selftest`\",\n        \"  并告诉他两件事：① 你的会话在 工作区 → 未分组 里（不点开看不见）② 要给那个会话「完全访问」权限\",\n        \"\",\n      ]\n    })(),\n    ...silenceLines(),\n    '按 AGENTS.md 的「看的那晚」流程走一遍（不要等我说话，直接做）：',\n    '⭐ **本轮硬规则（2026-10-23 主人定）：至少发一条主动评论（见 4.7）；鱼群泛滥时强制聚拢，不许以“没有可聚拢鱼楼”跳过；额度/冷却满了除外。**',\n    '1) `node bili.mjs deps` —— 体检红着就报备我、只做读、别对外发',\n    '2) 读两本日记（`~/.dsh/surfcore/bili/whale-diary.md` + `whale-diary-private.md`）',\n    // 2026-10-20：feed 已默认多源（搜索+热门+排行+关注）+ 去播放量偏向 + 偏好命中权重 ✓\n    // 2026-10-23：feed 改成按「口味权重」分名额 + 排除观看历史/最近推过的 + 搜索页轮换。\n    '3) `feed` 选题（≤5 条）→ 对这 5 条跑 `debrief --no-frames`',\n    '   （按设置页的「口味权重」分配条数、偏好之间轮转；看过的/最近推过的自动排除，**不看播放量** ✓）',\n    '   3.2) 如果你发现自己总在看同一类：不要自己改配置文件 —— 让主人去设置页「B站 → 口味权重 / 一键抓取」调低那个词、调高别的。'