{});\n    } catch {}\n  }\n\n  function sendToQQ(key, msg, opts = {}) {\n    const assertSendAllowed = captureSendGuard(key);\n    const safeMsg = redactKnownTokensOnly(msg);\n    const [kind, id] = key.split(':');\n    if (kind === 'group') recordFishWindow(key, '我', selfUserId, { isSelf: true });\n    const parts = splitForQQ(safeMsg);\n    lastSendFailed.delete(key);\n    for (const part of parts) {\n      sendChain = sendChain\n        .then(async () => {\n          assertSendAllowed();\n          if (kind === 'private') await withTimeout(bot.sendPrivateMessage(Number(id), text(escapeCqText(part))), SEND_TIMEOUT_MS, `QQ发送 ${kind}:${id}`);\n          else await withTimeout(bot.sendGroupMessage(Number(id), text(escapeCqText(part))), SEND_TIMEOUT_MS, `QQ发送 ${kind}:${id}`);\n          noteSendSuccess(key);\n          if (opts.mirror !== false && kind === 'private') mirrorPetMessage({ role: 'assistant', key, sender: '', text: part });\n        })\n        .catch((error) => {\n          lastSendFailed.set(key, true);\n          noteSendFailure(key, error);\n          log(`QQ 发送失败 (${key}):`, error?.message ?? error);\n        })\n        .then(() => sleep(cfg.sendDelayMs));\n    }\n    return sendChain;\n  }\n\n  /** 上一批发往该会话的消息是否全部成功。 */\n  function lastSendSucceeded(key) {\n    return lastSendFailed.get(key) !== true;\n  }\n\n  // ── 真人式分条发送 ──────────────────────────────────────────────────────\n  function singleLineForQQ(s) {\n    return String(s ?? '')\n      .replace(/\\s*\\n\\s*/g, ' ')\n      .replace(/[ \\t]{2,}/g, ' ')\n      .trim();\n  }\n\n  // 超长段落：先按次要标点拆，再按字符硬拆，保证不丢内容、不退回单条长消息。\n  // URL 会被当作不可拆分的原子，避免把 https://... 这种整条网页地址拆断。\n  function splitLongSegment(segment, max) {\n    const s = String(segment ?? '').trim();\n    if (!s) return [];\n    const safeMax = Number.isFinite(max) && max >= 1 ? Math.floor(max) : 500;\n    if (s.length <= safeMax) return [s];\n\n    const urlRe = /https?:\\/\\/[^\\s，。；、]+/g;\n    const urls = [];\n    const masked = s.re