vation window. An increase is\n    // recorded separately and never subtracts previously observed consumption.\n    function recordLedgerUsage(currentBalance, currency, scope, at) {\n      const led = readUsageLedger()\n      observeBalance(led, { balance: currentBalance, currency, scope, at })\n      pruneLedgerUsage(led)\n      if (!writeUsageLedger(led)) throw new Error('账本保存失败，请检查 DSH 数据目录写入权限')\n      return led\n    }\n    function normalizeUsageMode() {\n      return 'ledger' // 小鲸鱼记账为唯一记账方式\n    }\n    function ledgerTodayTotal(led) { return daySummary(led, todayKey()).amount }\n\n    function publicBalance(payload) {\n      const { accountTag, ...visible } = payload\n      const led = readUsageLedger()\n      const summary = daySummary(led, todayKey())\n      const nowSec = Math.floor(Date.now() / 1000)\n      // 平台用量同步（可选）优先：官方口径的今日消费比\"余额差\"更权威（能对上 Platform 用量页）。\n      // 没配 userToken / 接口失败时静默回落余额差口径，行为与旧版一致。\n      const plat = platformUsageCache\n      // 只有平台给出**正的**今日消费时才采用。原实现只判\"是数字\"⇒ 平台返回 0（UTC 切日导致\n      // 北京时间 0–8 点归入昨天，或接口偶发空数据）会把正确的余额口径覆盖成 0，\n      // 表现为「今日已用」反复闪 0 / 点击后丢失。0 时回落到余额差口径。\n      const platCost = plat && plat.today ? Number(plat.today.cost) : NaN\n      const usePlat = isFinite(platCost) && platCost > 0\n      return {\n        ...visible, version: BUILD_VERSION, versionLabel: VERSION_LABEL, isPeak: isPeakTime(nowSec),\n        // 峰谷切换点与节假日清单：前端倒计时要与宿主同源（否则法定节假日会算错切换点）\n        peakNextChangeAt: nextPeakChangeAt(nowSec),\n        peakHolidays: HOLIDAY_VALLEY_LIST,\n        todayUsage: usePlat ? Math.round(platCost * 1e8) / 1e8 : summary.amount,\n        todayUsageCurrency: usePlat ? String(plat.currency || 'CNY') : summary.currency,\n        usageSource: usePlat ? 'platform' : summary.source,\n        usageLabel: usePlat ? '平台用量' : summary.label,\n        usageMode: 'ledger',\n        // 给前端展示「本月」与平台分模型用量；未配置时 null\n        platformUsage: plat ? { today: plat.today, month: plat.month, models: plat.models, at: plat.at } : nul