ata', (c) => {\n          if (settled) return // 已超限：继续消费但不缓冲，避免连接被掐断\n          size += c.length\n          if (size > limit) {\n            const err = new Error('body too large')\n            err.code = 'BODY_TOO_LARGE'\n            err.status = 413\n            fail(err)\n            return\n          }\n          chunks.push(c)\n        })\n        req.on('end', () => { if (!settled) { settled = true; resolve(Buffer.concat(chunks).toString('utf8')) } })\n        req.on('error', (err) => fail(err))\n      })\n    }\n    function readBody(req) { return readBodyLimit(req, 8192) }\n    function readBodyMax(req, maxBytes) { return readBodyLimit(req, maxBytes) }\n\n    // —— 自定义角色存储：whale-roles/ 目录，每个角色一个 <id>.png + roles.json 索引 ——\n    function pickRoleDir() {\n      for (const p of ROLE_DIR_CANDIDATES) {\n        try {\n          fs.mkdirSync(p, { recursive: true })\n          fs.accessSync(p, fs.constants.W_OK)\n          return p\n        } catch (err) {}\n      }\n      return ROLE_DIR_CANDIDATES[0]\n    }\n\n    function defaultRolesIndex() {\n      return {\n        version: 1,\n        roles: [\n          // 默认小鲸鱼初始置顶；pinnedAt=1 作为基线，任何新置顶（Date.now()）都会排在它上面\n          { id: ROLE_DEFAULT_ID, name: '小鲸鱼', pinnedAt: 1, createdAt: 0 },\n        ],\n      }\n    }\n\n    function readRolesIndex() {\n      const dir = pickRoleDir()\n      try {\n        const parsed = JSON.parse(fs.readFileSync(path.join(dir, ROLE_INDEX_NAME), 'utf8'))\n        if (parsed && Array.isArray(parsed.roles)) {\n          if (!parsed.roles.some((r) => r && r.id === ROLE_DEFAULT_ID)) {\n            parsed.roles.unshift(defaultRolesIndex().roles[0])\n          }\n          return parsed\n        }\n      } catch (err) {}\n      return defaultRolesIndex()\n    }\n\n    function writeRolesIndex(index) {\n      const dir = pickRoleDir()\n      try {\n        fs.writeFileSync(path.join(dir, ROLE_INDEX_NAME), JSON.stringify(index, null, 2), 'utf8')\n        return true\n      } catch (err) {\n        return false\n      }\n    }\n\n    // 排序：置顶的在前（pinnedAt 大者先，即最新置顶在最上面），未置顶按创建时间倒序\n    function sortRoles(roles) {\n      return roles.slice().sort((a, b) => {\n        const ap = a.pinnedAt && a.pinnedAt > 0 ? a.pinnedAt : 0\n        const bp = b.pinnedAt && b.pinnedAt > 0 ? b.pinnedAt : 0\n        if (ap && bp) return bp - ap\n        if (ap) return -1\n        if (bp) return 1\n        return (b.createdAt || 0) - (a.createdAt || 0)\n      })\n    }\n\n    function rolesPayload() {\n      const index = readRolesIndex()\n      return {\n        ok: true,\n        roles: sortRoles(index.roles).map((r) => ({\n          id: r.id,\n          name: String(r.name || r.id),\n          url: r.id === ROLE_DEFAULT_ID ? '/dsh-whale/image.png' : '/dsh-whale/role-image.png?id=' + encodeURIComponent(r.id),\n          pinned: !!(r.pinnedAt && r.pinnedAt > 0),\n          pinnedAt: r.pinnedAt || null,\n          createdAt: r.createdAt || null,\n          // format: 'png' | 'gif' | 'apng'（旧角色无 format 字段 → png）\n          format: r.format === 'gif' || r.format === 'apng' ? r.format : 'png',\n        })),\n      }\n    }\n\n    // 角色文件按格式映射扩展名：gif→.gif，apng/png→.png（APNG 文件仍是 PNG 容器）\n    function roleFileExt(format) {\n      return format === 'gif' ? 'gif' : 'png'\n    }\n\n    function roleFilePath(id, format) {\n      if (typeof id !== 'string' || !/^[A-Za-z0-9_-]{1,64}$/.test(id) || id === ROLE_DEFAULT_ID) return null\n      return path.join(pickRoleDir(), id + '.' + roleFileExt(format))\n    }\n\n    function roleImagePath(id) {\n      // 查找角色元数据确定扩展名；找不到默认 png\n      const { role } = roleIndexFind(id)\n      const format = role && (role.format === 'gif' || role.format === 'apng') ? role.format : 'png'\n      const p = roleFilePath(id, format)\n      return p\n    }\n\n    function roleIdFromUrl(url) {\n      try {\n        const q = String(url || '').split('?')[1] || ''\n        const m = /(?:^|&)id=([^&]+)/.exec(q)\n        return m ? decodeURIComponent(m[1]) : ''\n      } catch (err) { return '' }\n    }\n\n    function roleIndexFind(id) {\n      const index = readRolesIndex()\n      const role = index.roles.find((r) => r && r.id === id)\n      return { index, role }\n    }\n\n    // —— 自定义音频：whale-audio/ 目录，片段 <id>.wav + audio.json 索引 ——\n    function pickAudioDir() {\n      for (const p of AUDIO_DIR_CANDIDATES) {\n        try {\n          fs.mkdirSync(p, { recursive: true })\n          fs.accessSync(p, fs.constants.W_OK)\n          return p\n        } catch (err) {}\n      }\n      return AUDIO_DIR_CANDIDATES[0]\n    }\n\n    function defaultAudioIndex() {\n      return { version: 1, groups: [], fragments: [] }\n    }\n\n    function readAudioIndex() {\n      const dir = pickAudioDir()\n      try {\n        const parsed = JSON.parse(fs.readFileSync(path.join(dir, AUDIO_INDEX_NAME), 'utf8'))\n        if (parsed && Array.isArray(parsed.groups) && Array.isArray(parsed.fragments)) {\n          return parsed\n        }\n      } catch (err) {}\n      return defaultAudioIndex()\n    }\n\n    function writeAudioIndex(index) {\n      const dir = pickAudioDir()\n      try {\n        fs.writeFileSync(path.join(dir, AUDIO_INDEX_NAME), JSON.stringify(index, null, 2), 'utf8')\n        return true\n      } catch (err) {\n        return false\n      }\n    }\n\n    // 自定义片段 id -> 文件路径；预设片段无文件\n    function audioFragmentPath(id) {\n      if (typeof id !== 'string' || !/^[A-Za-z0-9_-]{1,64}$/.test(id)) return null\n      if (PRESET_FRAGMENTS[id]) return null\n      return path.join(pickAudioDir(), id + '.wav')\n    }\n\n    function audioIdFromUrl(url) {\n      try {\n        const q = String(url || '').split('?')[1] || ''\n        const m = /(?:^|&)id=([^&]+)/.exec(q)\n        return m ? decodeURIComponent(m[1]) : ''\n      } catch (err) { return '' }\n    }\n\n    // 片段列表：预设片段 + 用户自定义片段\n    function audioFragmentsPayload() {\n      const index = readAudioIndex()\n      const presets = Object.keys(PRESET_FRAGMENTS).map((k) => ({\n        id: k,\n        name: PRESET_FRAGMENTS[k].name,\n        preset: true,\n      }))\n      const custom = index.fragments.map((f) => ({\n        id: f.id,\n        name: String(f.name || f.id),\n        preset: false,\n        createdAt: f.createdAt || null,\n      }))\n      return presets.concat(custom)\n    }\n\n    // 音效组列表：预设组 + 用户自定义组（置顶优先，组内按创建时间倒序）\n    function audioGroupsPayload() {\n      const index = readAudioIndex()\n      // 排序：置顶的自定义组最前，其次预设组，最后未置顶的自定义组（按创建时间倒序）\n      const customs = index.groups.slice().map((g) => ({\n        id: g.id,\n        name: String(g.name || g.id),\n        press: typeof g.press === 'string' ? g.press : null,\n        release: typeof g.release === 'string' ? g.release : null,\n        preset: false,\n        pinned: !!(g.pinnedAt && g.pinnedAt > 0),\n        pinnedAt: g.pinnedAt || null,\n        createdAt: g.createdAt || 0,\n      }))\n      const pinned = customs.filter((g) => g.pinned).sort((a, b) => b.pinnedAt - a.pinnedAt)\n      const unpinned = customs.filter((g) => !g.pinned).sort((a, b) => b.createdAt - a.createdAt)\n      const presets = Object.keys(PRESET_GROUPS).map((k) => {\n        const g = PRESET_GROUPS[k]\n        return { id: g.id, name: g.name, press: g.press, release: g.release, preset: true, pinned: false, pinnedAt: null, createdAt: 0 }\n      })\n      return pinned.concat(presets, unpinned)\n    }\n\n    function audioPayload() {\n      return {\n        ok: true,\n        groups: audioGroupsPayload(),\n        fragments: audioFragmentsPayload(),\n      }\n    }\n\n    // 取片段音频字节：内置随包片段 → 预设(SOUND_SETS) → 自定义 whale-audio/<id>.wav\n    function loadAudioFragmentBytes(fragId) {\n      if (BUILTIN_FRAGMENT_FILES[fragId]) {\n        return loadSound(BUILTIN_FRAGMENT_FILES[fragId])\n      }\n      if (PRESET_FRAGMENTS[fragId]) {\n        // 预设片段映射到对应音效文件：ya1->duck.press, ya2->duck.release, d1->fx1.press, d2->fx1.release\n        const map = { ya1: ['duck', 'press'], ya2: ['duck', 'release'], d1: ['fx1', 'press'], d2: ['fx1', 'release'], ya3: ['duck2', 'press'], vb: ['voice_bing', 'press'], vh: ['voice_heng', 'press'], vq: ['voice_qtan', 'press'], vw: ['voice_weiqu', 'press'] }\n        const [setName, slot] = map[fragId]\n        const set = SOUND_SETS[setName]\n        if (!set) return null\n        return loadSound(set[slot])\n      }\n      const p = audioFragmentPath(fragId)\n      if (!p) return null\n      try {\n        const bytes = fs.readFileSync(p)\n        if (bytes && bytes.length > 0) return bytes\n      } catch (err) {}\n      return null\n    }\n\n    // 组内实际使用的片段：若自定义组引用的片段被删，回退到预设\n    // 返回 '' 表示该槽显式留空（该事件静音），调用方应据此不发音频\n    function groupFragmentId(groupId, slot) {\n      const custom = readAudioIndex().groups.find((g) => g && g.id === groupId)\n      if (custom) {\n        const fid = custom[slot]\n        if (fid === '') return ''\n        if (fid) {\n          if (PRESET_FRAGMENTS[fid]) return fid\n          if (customFragExists(fid)) return fid\n        }\n        // 无字段/引用失效 → 回退预设：新组无引用时用 duck\n        return slot === 'press' ? PRESET_GROUPS.duck.press : PRESET_GROUPS.duck.release\n      }\n      const preset = PRESET_GROUPS[groupId]\n      if (preset) return preset[slot]\n      return slot === 'press' ? PRESET_GROUPS.duck.press : PRESET_GROUPS.duck.release\n    }\n\n    function customFragExists(id) {\n      try {\n        const p = audioFragmentPath(id)\n        if (!p) return false\n        const st = fs.statSync(p)\n        return st.isFile()\n      } catch (err) { return false }\n    }\n\n    disposers.push(registerRoute({\n      kind: 'exact',\n      path: '/dsh-whale/image.png',\n      handler: (req, res) => {\n        try {\n          const bytes = loadImage()\n          res.writeHead(200, {\n            'Content-Type': 'image/png',\n            'Cache-Control': 'no-store',\n            'Content-Length': String(bytes.length),\n          })\n          res.end(bytes)\n        } catch (err) {\n          res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' })\n          res.end('whale image unavailable: ' + String((err && err.message) || err))\n        }\n      },\n    }))\n\n    disposers.push(registerRoute({\n      kind: 'exact',\n      path: '/dsh-whale/rua.gif',\n      handler: (req, res) => {\n        try {\n          const bytes = loadGif()\n          res.writeHead(200, {\n            'Content-Type': 'image/gif',\n            'Cache-Control': 'no-store',\n            'Content-Length': String(bytes.length),\n          })\n          res.end(bytes)\n        } catch (err) {\n          res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' })\n          res.end('rua gif unavailable: ' + String((err && err.message) || err))\n        }\n      },\n    }))\n\n    // ===== 平台用量同步（可选）：DeepSeek Platform 私有用量接口 =====\n    // 为什么需要：插件自己的「今日已用」是余额差口径；「每轮消耗」是 token×价目表折算。\n    // 平台的用量接口给出官方口径的 token 与消费，需要一次性配置：在 platform.deepseek.com\n    // 登录后从浏览器控制台取 `userToken` 粘贴进来（凭据名 DEEPSEEK_USER_TOKEN，存 DSH 凭据服务）。\n    // ===== 复用官方平台登录态（桌面端零配置）=====\n    // 官方组合里的账号服务（dsh-deepseek-account-platform）在 Host 侧暴露\n    // getPlatformSession() → { origin, token, requestHeaders }。插件本身就跑在 Host 里，\n    // 所以可以直接拿这份「设置 → 账号与余额」正在使用的平台登录态去调用量接口 ——\n    // 用户不需要粘贴任何 token。Web（npm dsh）组合里没有该服务 ⇒ 该分支静默不激活，\n    // 回落到手动 userToken / 余额差口径。\n    let accountCtx = null\n    try {\n      ctx.inject(['deepseekAccount'], (acc) => {\n        accountCtx = acc\n        acc.effect(() => () => { accountCtx = null })\n      })\n    } catch (err) {}\n    async function officialPlatformSession() {\n      try {\n        if (!accountCtx || !accountCtx.deepseekAccount) return null\n        const s = await accountCtx.deepseekAccount.getPlatformSession()\n        if (!s || !s.origin || !s.token) return null\n        return { origin: String(s.origin), token: String(s.token), headers: s.requestHeaders || {} }\n      } catch (err) { return null }\n    }\n    const PLATFORM_USAGE_TTL_MS = 120000\n    let platformUsageCache = null\n    let platformUsageAt = 0\n    let platformUsageCode = ''\n    let platformUsageSource = '' // 'official'（桌面端复用官方登录态）| 'token'（手动 userToken）\n    async function platformUserToken() {\n      try {\n        const cred = await ctx.credentials.resolve('DEEPSEEK_USER_TOKEN')\n        if (!cred) return ''\n        const v = typeof cred === 'string' ? cred : (cred.value || cred.secret || cred.token || '')\n        return String(v || '')\n      } catch (err) { return '' }\n    }\n    function toNumSafe(v) { const n = Number(v); return isFinite(n) ? n : 0 }\n    function summarizePlatformUsage(amountData, costData) {\n      const biz = (amountData && amountData.data && amountData.data.biz_data) || {}\n      const costBiz = costData && costData.data && costData.data.biz_data\n      const costItem = (Array.isArray(costBiz) && costBiz[0]) || {}\n      const currency = costItem.currency || 'CNY'\n      let monthTokens = 0\n      let monthRequests = 0\n      const modelTokens = {}\n      const modelCost = {}\n      ;(biz.total || []).forEach((m) => {\n        let mt = 0\n        ;(m.usage || []).forEach((u) => {\n          const t = String(u.type || '')\n          const n = toNumSafe(u.amount)\n          if (t === 'REQUEST') monthRequests += n\n          else mt += n\n        })\n        if (m.model) modelTokens[m.model] = (modelTokens[m.model] || 0) + mt\n        monthTokens += mt\n      })\n      let monthCost = 0\n      ;(costItem.total || []).forEach((m) => {\n        let c = 0\n        ;(m.usage || []).forEach((u) => { if (String(u.type || '') !== 'REQUEST') c += toNumSafe(u.amount) })\n        monthCost += c\n        if (m.model) modelCost[m.model] = (modelCost[m.model] || 0) + c\n      })\n      // 平台日数据按 UTC 切分（本地 0:00-8:00 归入 UTC 昨天）；今日按 UTC 日期取\n      const dayCost = {}\n      const dayTokens = {}\n      ;(costItem.days || []).forEach((d) => {\n        let c = 0\n        ;(d.data || []).forEach((m) => { (m.usage || []).forEach((u) => { if (String(u.type || '') !== 'REQUEST') c += toNumSafe(u.amount) }) })\n        if (d.date) dayCost[d.date] = c\n      })\n      ;(biz.days || []).forEach((d) => {\n        let tk = 0\n        ;(d.data || []).forEach((m) => { (m.usage || []).forEach((u) => { if (String(u.type || '') !== 'REQUEST') tk += toNumSafe(u.amount) }) })\n        if (d.date) dayTokens[d.date] = tk\n      })\n      const dt = new Date()\n      const p2 = (n) => (n < 10 ? '0' + n : String(n))\n      const today = dt.getUTCFullYear() + '-' + p2(dt.getUTCMonth() + 1) + '-' + p2(dt.getUTCDate())\n      const models = Object.keys(modelTokens).map((model) => ({ model: model, tokens: modelTokens[model] || 0, cost: modelCost[model] || 0 })).sort((a, b) => b.tokens - a.tokens).slice(0, 20)\n      return {\n        currency: currency,\n        month: { tokens: monthTokens, cost: monthCost, requests: monthRequests },\n        today: { tokens: dayTokens[today] || 0, cost: dayCost[today] || 0 },\n        models: models,\n        at: Date.now(),\n      }\n    }\n    // v882（审查发现，稳定性）：这个函数原来有两个坑：\n    //   ① 两个 fetch **都没有超时**（Node/undici 默认 headersTimeout 300s）——平台侧一旦不响应，\n    //      请求会挂好几分钟，期间每次 /balance.json 都会在后台再发起一对新请求，连接只增不减；\n    //   ② **没有在途去重**：并发请求（前端每秒轮询 wait/balance）会各发一对，形成请求风暴。\n    //   所以：加超时 + 复用在途 Promise（失败后自然被 finally 清掉，下次重新取）。\n    const PLATFORM_USAGE_TIMEOUT_MS = 8000\n    let platformUsageInFlight = null\n    async function fetchPlatformUsage(force) {\n      const now = Date.now()\n      if (!force && platformUsageCache && now - platformUsageAt < PLATFORM_USAGE_TTL_MS) return platformUsageCache\n      if (platformUsageInFlight) return platformUsageInFlight\n      platformUsageInFlight = fetchPlatformUsageOnce().finally(() => { platformUsageInFlight = null })\n      return platformUsageInFlight\n    }\n    async function fetchPlatformUsageOnce() {\n      const now = Date.now()\n      // 凭据来源优先级：① 官方登录态（桌面端零配置）② 手动 DEEPSEEK_USER_TOKEN（Web 端）\n      let origin = 'https://platform.deepseek.com'\n      let token = ''\n      let extraHeaders = {}\n      let source = ''\n      const official = await officialPlatformSession()\n      if (official) {\n        origin = official.origin\n        token = official.token\n        extraHeaders = official.headers || {}\n        source = 'official'\n      } else {\n        token = await platformUserToken()\n        if (token) source = 'token'\n      }\n      if (!token) { platformUsageCode = 'NO_TOKEN'; return null }\n      platformUsageSource = source\n      try {\n        const d = new Date()\n        const qs = '?month=' + (d.getMonth() + 1) + '&year=' + d.getFullYear()\n        const headers = Object.assign({}, extraHeaders, { authorization: 'Bearer ' + token, referer: origin + '/usage', accept: 'application/json' })\n        const [a, c] = await Promise.all([\n          fetch(origin + '/api/v0/usage/amount' + qs, { headers: headers, signal: AbortSignal.timeout(PLATFORM_USAGE_TIMEOUT_MS) }),\n          fetch(origin + '/api/v0/usage/cost' + qs, { headers: headers, signal: AbortSignal.timeout(PLATFORM_USAGE_TIMEOUT_MS) }),\n        ])\n        if (a.status === 401 || c.status === 401 || a.status === 403 || c.status === 403) { platformUsageCode = 'AUTH_FAILED'; return null }\n        if (!a.ok || !c.ok) { platformUsageCode = 'HTTP_' + a.status; return null }\n        const aj = await a.json()\n        const cj = await c.json()\n        const computed = summarizePlatformUsage(aj, cj)\n        platformUsageCache = computed\n        platformUsageAt = now\n        platformUsageCode = ''\n        return computed\n      } catch (err) {\n        platformUsageCode = 'NETWORK'\n        return null\n      }\n    }\n    disposers.push(registerRoute({\n      kind: 'exact',\n      path: '/dsh-whale/platform-usage.json',\n      handler: async (req, res) => {\n        try {\n          const refresh = new URL(req.url || '/', 'http://localhost').searchParams.get('refresh') === '1'\n          const data = await fetchPlatformUsage(refresh)\n          res.writeHead(200, JSON_HEADERS)\n          res.end(JSON.stringify(data ? Object.assign({ ok: true, source: platformUsageSource }, data) : { ok: false, code: platformUsageCode || 'NO_TOKEN' }))\n        } catch (err) {\n          res.writeHead(500, JSON_HEADERS)\n          res.end(JSON.stringify({ ok: false, code: 'ERROR' }))\n        }\n      },\n    }))\n    disposers.push(registerRoute({\n      kind: 'exact',\n      path: '/dsh-whale/platform-token.json',\n      handler: async (req, res) => {\n        try {\n          if (req.method === 'PUT' || req.method === 'POST') {\n            const raw = await readBody(req)\n            let body = null\n            try { body = JSON.parse(raw || '{}') } catch (err) { body = null }\n            const token = String((body && body.token) || '').trim()\n            if (!token) {\n              res.writeHead(400, JSON_HEADERS)\n              res.end(JSON.stringify({ ok: false, code: 'EMPTY' }))\n              return\n            }\n            await ctx.credentials.set('DEEPSEEK_USER_TOKEN', token)\n            platformUsageCache = null\n            platformUsageAt = 0\n            const data = await fetchPlatformUsage(true)\n            res.writeHead(200, JSON_HEADERS)\n            res.end(JSON.stringify(data ? Object.assign({ ok: true, source: platformUsageSource }, data) : { ok: false, code: platformUsageCode || 'AUTH_FAILED' }))\n            return\n          }\n          res.writeHead(405, JSON_HEADERS)\n          res.end(JSON.stringify({ ok: false, code: 'METHOD' }))\n        } catch (err) {\n          // v882：读体超限（BODY_TOO_LARGE）带 status=413 —— 照抄它，别一律报 500\n          res.writeHead(Number(err && err.status) || 500, JSON_HEADERS)\n          res.end(JSON.stringify({ ok: false, code: 'ERROR', error: String((err && err.message) || err).slice(0, 160) }))\n        }\n      },\n    }))\n\n    disposers.push(registerRoute({\n      kind: 'exact',\n      path: '/dsh-whale/balance.json',\n      handler: async (req, res) => {\n        // v882（审查发现）：这里原来没有 `t0`，而下面两处 `Date.now() - t0` 都写在 try/catch 里\n        //   ⇒ ReferenceError 被静默吞掉，`balanceLast` **永远是 null**，「关于/自检」面板的\n        //   「余额取数」一行因此永远显示\"本次会话尚未取过\"。t0 必须在取数前就位。\n        const t0 = Date.now()\n        // 后台刷新平台用量（不阻塞本次响应；有缓存时响应里直接用缓存值）\n        try { fetchPlatformUsage(false).catch(function () {}) } catch (err) {}\n        try {\n          const refresh = new URL(req.url || '/', 'http://localhost').searchParams.get('refresh') === '1'\n          const payload = await getBalance(refresh)\n          // v793：给「关于/自检」面板留一条最近的取数结果（只记状态与耗时，不记任何凭据）\n          try {\n            balanceLast = {\n              at: Date.now(),\n              ms: Date.now() - t0,\n              ok: !!payload.ok,\n              code: String(payload.code || ''),\n              error: payload.ok ? '' : String(payload.error || '').slice(0, 160),\n              hasBalance: payload.totalBalance !== null && payload.totalBalance !== undefined,\n              currency: String(payload.currency || ''),\n            }\n          } catch (err) {}\n          res.writeHead(200, JSON_HEADERS)\n          // v794：成功失败都带上版本 ⇒ 客户端不必依赖\"余额成功\"才拿到版号\n          res.end(JSON.stringify(Object.assign({}, payload, { version: BUILD_VERSION, versionLabel: VERSION_LABEL })))\n        } catch (err) {\n          try {\n            balanceLast = { at: Date.now(), ms: Date.now() - t0, ok: false, code: 'THROW', error: String((err && err.message) || err).slice(0, 160), hasBalance: false, currency: '' }\n          } catch (e2) {}\n          res.writeHead(200, JSON_HEADERS)\n          res.end(JSON.stringify({ ok: false, code: 'ERROR', error: String((err && err.message) || err).slice(0, 200), version: BUILD_VERSION, versionLabel: VERSION_LABEL }))\n        }\n      },\n    }))\n\n    disposers.push(registerRoute({\n      kind: 'exact',\n      path: '/dsh-whale/last-turn.json',\n      handler: (req, res) => {\n        // 返回最近一轮已完成的对话消耗；seq 递增供前端判断「新的一轮」\n        // unpriced/unpricedTokens：本轮有第三方模型没配单价（金额不